        "Í bókstaflegri merkingu þýðir angebracht líka festur eða komið fyrir: Das Schild ist an der Tür angebracht (skiltið er fest á hurðina). Þetta er sama lýsingarháttarmyndin af anbringen (bringt an, brachte an, hat angebracht)."
