      "explanation": [
        "Meginhugmynd: fleckig er lýsingarorð sem lýsir yfirborði með blettum eða flekkjum — óhreinni flík, húð með blettum, flekkóttum feldi dýrs.",
        "Stigbreyting: fleckig, fleckiger, am fleckigsten. Notað bæði með nafnorði (ein fleckiges Hemd) og á eftir sein (Das Hemd ist fleckig). Stofnorðið er der Fleck (blettur, skylt íslensku flekkur), fleirtala die Flecken."
      ],
      "examples": [
        {
          "de": "Die Tischdecke ist fleckig.",
          "lv": "Borðdúkurinn er blettóttur."
        },
        {
          "de": "Das Hemd ist nach dem Essen fleckig.",
          "lv": "Skyrtan er öll í blettum eftir matinn."
        },
        {
          "de": "Seine Haut war rot und fleckig.",
          "lv": "Húð hans var rauð og flekkótt."
        },
        {
          "de": "Die Kuh hat ein fleckiges Fell.",
          "lv": "Kýrin er með flekkóttan feld."
        },
        {
          "de": "Das Pferd hat ein braun-weißes, fleckiges Fell.",
          "lv": "Hesturinn er brúnskjóttur."
        }
      ],
      "comparison": [
        {
          "word": "gefleckt",
          "meaning": "flekkóttur • skjóttur",
          "example": "Der Hund ist schwarz-weiß gefleckt. – Hundurinn er svart- og hvítflekkóttur."
        },
        {
          "word": "schmutzig",
          "meaning": "óhreinn",
          "example": "Die Hose ist schmutzig. – Buxurnar eru óhreinar."
        },
        {
          "word": "gestreift",
          "meaning": "röndóttur",
          "example": "Er trägt ein gestreiftes Hemd. – Hann er í röndóttri skyrtu."
        }
      ],
      "tip": [
        "Hugsaðu um der Fleck: fleckig er það sem er með Flecken.",
        "Til að lýsa náttúrulegum flekkjum á dýri er oft notað gefleckt."
      ],
      "important": [
        "fleckig lýsir oft óæskilegu eða ójöfnu útliti (óhrein flík, rauðir blettir á húð).",
        "Þegar beygingarendingu er bætt við, mundu e-ið: ein fleckiges Fell, eine fleckige Haut."
      ],
