      "translation": "glóð • hiti",
      "explanation": [
        "Meginhugmynd: die Glut er kvenkynsnafnorð, skylt íslenska kvenkynsorðinu glóð. Það merkir glóandi kol eða heita glóð kulnandi elds, og einnig mjög mikinn, brennandi hita (die Glut der Sonne). Í yfirfærðri merkingu er Glut einnig ástríða, eldmóður.",
        "Fleirtalan er sjaldgæf (die Gluten), venjulega er notuð eintala: die Glut. Algengir frasar: die Glut anfachen (blása í glæðurnar), unter der Asche glimmt noch Glut (undir öskunni leynist enn glóð)."
      ],
      "examples": [
        {
          "de": "Die Glut des Lagerfeuers wärmte uns noch.",
          "lv": "Glóðin í varðeldinum yljaði okkur enn."
        },
        {
          "de": "In der Glut der Mittagssonne ruhte das ganze Dorf.",
          "lv": "Í steikjandi hádegishitanum hvíldist allt þorpið."
        },
        {
          "de": "Er blies in die Glut, bis wieder Flammen aufstiegen.",
          "lv": "Hann blés í glóðina þar til logarnir blossuðu upp aftur."
        },
        {
          "de": "Mit großer Glut sprach sie über ihr Projekt.",
          "lv": "Hún talaði af miklum eldmóði um verkefnið sitt."
        }
      ],
      "comparison": [
        {
          "word": "die Hitze",
          "meaning": "hiti",
          "example": "Im Sommer ist die Hitze groß. – Á sumrin er hitinn mikill."
        },
        {
          "word": "die Asche",
          "meaning": "aska",
          "example": "Unter der Asche liegt noch Glut. – Undir öskunni er enn glóð."
        },
        {
          "word": "die Flamme",
          "meaning": "logi",
          "example": "Die Flamme wird kleiner. – Loginn minnkar."
        }
      ],
      "tip": [
        "Glut lýsir rauðri glóðinni sem eftir er af eldi, en Flamme — sýnilegum loga.",
        "Í tengslum við varðeld skaltu læra: Feuer — eldur, Flamme — logi, Glut — glóandi kol."
      ],
      "important": [
        "Glut er venjulega í eintölu; fleirtalan die Gluten er mjög sjaldgæf.",
        "Til að lýsa venjulegum hita nægir die Hitze; Glut hljómar sterkara, skáldlegra."
      ],
